        '2012.3.23092012.Away.Bears', c(1,2,2,3,4,4,4), c(10.41,1.56,0.22,6.14,9.45,9.6,2.18), c(F,F,T,T,F,F,F), c(3,7,3,3,3,7,3),
        '2012.4.30092012.Home.Seahawks', c(1,1,2,2,3,3,4,4), c(10.45,4.59,1.11,0.0,13.46,4.10,13.3,6.7), c(F,T,T,T,T,F,F,T), c(7,3,7,3,3,3,3,3),
        '2012.5.04102012.Home.Cardinals', c(1,1,2,4), c(12.39,3.15,10.45,11.49), c(T,F,T,T), c(7,3,3,7),
        '2012.6.14102012.Away.Dolphins', c(1,1,2,2,3,4), c(12.25,5.8,5.27,4.19,9.40,8.30), c(T,T,F,F,F,T), c(3,3,7,3,7,8),
        '2012.7.21102012.Home.Packers', c(1,1,1,2,3,4,4,4,4,4), c(7.38,5.23,2.17,0.40,8.4,11.52,8.50,3.6,1.49,0.15), c(T,F,F,T,F,F,T,F,F,T), c(3,7,3,3,7,3,7,7,3,7),
        '2012.8.28102012.Home.Patriots', c(1,1,2,2,2,3,3,4), c(12.25,7.50,14.12,6.26,0.10,12.24,6.55,11.20), c(T,F,F,F,F,F,F,F), c(7,7,7,7,7,7,3,7),
        '2012.10.11112012.Away.49ers', c(1,1,2,3,4,4,4,4), c(9.38,1.47,8.13,0.18,8.40,8.23,1.9,0.3), c(T,T,F,T,F,F,T,F), c(7,7,7,3,7,7,7,3),
        '2012.11.18112012.Home.Jets', c(1,1,2,2,4,4,4), c(3.45,0.44,4.31,0.57,14.16,8.29,5.40), c(T,F,F,F,F,F,T), c(7,3,7,3,7,7,6),
        '2012.12.25112012.Away.Cardinals', c(1,2,2,2,2,3,3,4), c(2.41,14.52,7.52,1.53,0.0,9.58,2.28,5.27), c(F,T,F,T,F,T,T,T), c(7,7,7,7,3,7,7,3),
        '2012.13.02122012.Home.49ers', c(1,3,4,4,4,4,5), c(2.58,4.27,8.43,3.4,1.34,0.0,0.26), c(F,T,F,T,F,T,T), c(7,2,3,8,3,3,3),
        '2012.14.09122012.Away.Bills', c(1,2,3,3,4), c(2.14,0.7,8.37,3.26,0.48), c(F,F,T,F,T), c(3,3,7,6,8),
        '2012.15.16122012.Home.Vikings', c(1,2,2,2,2,2,2,3,4,4,4), c(7.7,12.39,12.21,9.11,8.25,3.11,0.0,5.56,13.39,7.48,5.31), c(F,T,F,F,F,F,F,F,T,T,F), c(7,7,7,3,7,3,3,3,7,8,3),
        '2012.16.23122012.Away.Buccaneers', c(1,2,2,2,3,3,3), c(5.22,11.46,5.56,0.32,14.46,10.47,8.50), c(F,T,F,T,T,T,F), c(3,7,3,7,7,7,7),
        '2012.17.30122012.Away.Seahawks', c(2,2,3,3,3,4,4), c(10.40,6.3,10.41,5.31,2.9,11.23,1.39), c(F,T,F,T,F,T,F), c(3,7,3,3,7,3,7)
) |> 
  separate(ID, sep = "\\.", into = c("Season", "Week", "Date", "Location", "Opponent"), convert = TRUE) |> 
  unnest(cols = c(Qtr, Time, Rams_Score, Pts)) |> 
  mutate(Date = dmy(Date),
         across(c(Qtr, Pts), ~ as.integer(.x)),
         Dur_Q = c(rep(900, 4), rep(ifelse(Season <= 2016 & Week < 30, 900, 600), 3))[Qtr],
         Dur_T = c(0, 900, 1800, 2700, 3600, ifelse(Season <= 2016 & Week < 30, c(4500, 5400), c(4200, 4800)))[Qtr]) |> 
  mutate(Time = Dur_Q - (trunc(Time) * 60 + Time %% 1 * 100) + Dur_T,
         .keep = "unused") -> scoredetail

# Zusammenfassung ----
scoredetail |> 
  group_by(Season, Week, Date, Location, Opponent) |> 
  summarise(
    Pts_Rams = sum(Pts[Rams_Score], na.rm = TRUE),
    Pts_Opp  = sum(Pts[!Rams_Score], na.rm = TRUE),
    OT       = max(Qtr) > 4,
    # Letzter Score oder mindestens 3600 Sekunden (End Regulation)
    Final_Score_Time = max(3600, max(Time, na.rm = TRUE)),
    .groups  = "drop"
  ) |> 
  mutate(
    Res   = case_when(Pts_Rams > Pts_Opp ~ "W", Pts_Rams < Pts_Opp ~ "L", TRUE ~ "T"),
    OT    = if_else(Res == "T", TRUE, OT),
    # Bei Tie volle OT-Dauer ansetzen, sonst Zeit des letzten Scores/Reg
    Final = case_when(
      Res == "T" & Season <= 2016 ~ 4500,
      Res == "T" & Season > 2016  ~ 4200,
      TRUE                        ~ Final_Score_Time
    )
  )|> 
  select(-Final_Score_Time)  -> he
  anti_join(results |>
              filter(Franchise == "Rams", Season >= 1999) |> 
              select(Season, Week, Date, PF, PA, Road, Opp_Fr),
            he |> 
              mutate(Opponent = case_when(Season < 2022 & Opponent == "Redskins" ~ "Commanders", TRUE ~ Opponent),
                     Road = case_when(Week == 35 ~ NA, TRUE ~ Location == "Away")),
            by = c("Season", "Week", "Date", "Opp_Fr" = "Opponent", "Road", "PF" = "Pts_Rams", "PA" = "Pts_Opp")); rm(he)
  
# Grafik ----
scoredetail |>
  # 1. Regular Season filtern
  filter(Week < 30, Season %in% 1999:2013) |>
  
  # 2. Spiel-Ebene: Final-Zeitpunkte berechnen
  group_by(Season, Week, Location, Opponent) |>
  mutate(
    Pts_Rams   = sum(Pts[Rams_Score], na.rm = TRUE),
    Pts_Opp    = sum(Pts[!Rams_Score], na.rm = TRUE),
    Last_Score = max(Time, na.rm = TRUE),
    Is_Tie     = (Pts_Rams == Pts_Opp),
    
    Game_Final = case_when(
      Is_Tie & Season <= 2016 ~ 4500,
      Is_Tie & Season > 2016  ~ 4200,
      TRUE                    ~ pmax(3600, Last_Score)
    )
  ) |>
  
  # 3. Saison-Ebene: Net Points & Endzeit ermitteln
  group_by(Season) |>
  mutate(
    PF_Rams      = if_else(Rams_Score, Pts, -Pts),
    n_games      = n_distinct(Week),
    Season_Final = max(Game_Final)
  ) |>
  
  # 4. Aggregation: Net Points pro Zeitpunkt
  group_by(Season, Time) |>
  summarise(
    NetPts       = sum(PF_Rams) / first(n_games),
    Season_Final = first(Season_Final),
    .groups      = "drop_last"
  ) |>
  arrange(Time) |>
  mutate(NetPts = cumsum(NetPts)) |>
  
  # 5. Ränder (0 und Season_Final) verankern
  group_modify(~ {
    s_final <- first(.x$Season_Final)
    
    if (! 0 %in% .x$Time) {
      .x <- add_row(.x, Time = 0, NetPts = 0, Season_Final = s_final, .before = 1)
    }
    
    last_pts <- tail(.x$NetPts, 1)
    if (! s_final %in% .x$Time) {
      .x <- add_row(.x, Time = s_final, NetPts = last_pts, Season_Final = s_final)
    }
    
    .x
  }) |>
  
  # 6. Punkte für hv-Stufen verdoppeln
  group_modify(~ {
    tibble(
      Time         = c(.x$Time[1], rep(.x$Time[-1], each = 2)),
      NetPts       = c(rep(.x$NetPts[-nrow(.x)], each = 2), .x$NetPts[nrow(.x)]),
      Season_Final = first(.x$Season_Final)
    )
  }) |>
  ungroup() |>
  
  # 7. Plot-Erstellung
  ggplot(aes(x = Time, y = NetPts)) +
  # OT-Hintergrund
  geom_rect(
    data = function(d) {
      d |> 
        group_by(Season) |> 
        summarise(max_t = max(Season_Final), .groups = "drop") |> 
        filter(max_t > 3600)
    },
    aes(xmin = 3600, xmax = max_t, ymin = -Inf, ymax = Inf),
    fill = "gray92", 
    inherit.aes = FALSE
  ) +
  
  # Stufenflächen
  geom_ribbon(aes(ymin = 0, ymax = pmax(0, NetPts)), fill = "forestgreen", alpha = 0.25) +
  geom_ribbon(aes(ymin = pmin(0, NetPts), ymax = 0), fill = "firebrick", alpha = 0.25) +
  
  # Referenzlinien
  geom_hline(yintercept = 0, color = "gray40", linewidth = 0.6) +
  geom_vline(xintercept = c(900, 1800, 2700, 3600), linetype = "dotted", color = "gray50") +
  
  # Durchgehende schwarze Stufenlinie
  geom_line(linewidth = 1.1, color = "black") +
  
  # Faceting
  facet_wrap(~Season, nrow = 5) +
  
  # Achsenbeschriftung
  scale_x_continuous(
    name = "Game Time",
    breaks = c(0, 900, 1800, 2700, 3600),
    labels = c("KO", "Q1", "HT", "Q3", "EoR")
  ) +
  
  # Y-Achse in 7er-Schritten
  scale_y_continuous(
    name = "Avg Net Points per Game",
    breaks = seq(-21, 21, by = 7)
  ) +
  
  labs(
    title = "Rams: Average Regular Season Game Net Points",
    subtitle = "Green = Point Lead | Red = Point Deficit | Gray = Overtime"
  ) +
  theme_minimal() +
  theme(
    strip.text       = element_text(face = "bold", size = 10, color = "black"),
    panel.grid.minor = element_blank()
  )
